CREATE OR REPLACE FUNCTION calculate_enrollment_rate(trial_id INT, target_date DATE)
RETURNS NUMERIC AS $$
DECLARE
  screened_count INT;
  enrolled_count INT;
  rate NUMERIC;
BEGIN
  SELECT 
    COUNT(*),
    COUNT(CASE WHEN enrollment_status = 'enrolled' THEN 1 END)
  INTO screened_count, enrolled_count
  FROM trial_participants
  WHERE trial_participants.trial_id = calculate_enrollment_rate.trial_id
    AND screening_date <= target_date;

  IF screened_count = 0 THEN
    RETURN 0.00;
  END IF;

  rate := ROUND((enrolled_count::NUMERIC / screened_count) * 100, 2);
  RETURN rate;
END;
$$ LANGUAGE plpgsql;

SELECT calculate_enrollment_rate(101, '2024-01-15') AS result;
